insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('7a83ca2f-82a6-4925-a1f1-e7cdb271bab2', '35e4bc54-ec50-4252-a16e-984ef858833e', $$onderzoek van Wageningen UR naar eendenkroos als veevoer$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context1.png$$,
   $$In 2007 startte Wageningen UR in samenwerking met het waterschap Vallei en Eem en twee melkveehouders een onderzoek naar de bruikbaarheid van eendenkroos als veevoer. De resultaten zijn veelbelovend: de voederwaarde is goed en het kroos wordt in gedroogde vorm goed gevreten door het vee.$$, 'inline'),
  ('ec3a4d17-c241-4b01-a40f-3789b4cc94ed', '35e4bc54-ec50-4252-a16e-984ef858833e', $$bouw van een eendenkroosblad zonder houtvaten en bastvaten (afbeelding 1 en 2)$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context2.png$$,
   $$Eendenkroos is een verzamelnaam voor een familie van zeer kleine drijvende waterplantjes. De groene blaadjes (zie afbeelding 1) bestaan vooral uit fotosynthetiserend weefsel en grote intercellulaire ruimten gevuld met lucht (zie afbeelding 2). Er zijn wel nerven, maar zonder houtvaten en bastvaten.
afbeelding 1: zwart-witfoto van drijvende kroosplantjes op het wateroppervlak.
afbeelding 2: tekening van een dwarsdoorsnede van een kroosblaadje, met parenchymweefsel en grote luchtruimten (intercellulaire ruimten) tussen de nerven.$$, 'inline'),
  ('54236e0c-2336-4bce-a15a-beac8135b08a', '35e4bc54-ec50-4252-a16e-984ef858833e', $$snelle vermeerdering van eendenkroos onder optimale omstandigheden$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context3.png$$,
   $$Het onderzoek richt zich onder andere op de beste omstandigheden om eendenkroos te kweken. De vermeerdering van kroos gaat extreem snel: onder optimale omstandigheden verdubbelt de massa in 16-48 uur.$$, 'inline'),
  ('41630ec4-e852-4f9f-9819-4a05e27c4382', '35e4bc54-ec50-4252-a16e-984ef858833e', $$dichte kroosbedekking op sloten in gebieden met intensieve landbouw$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context4.png$$,
   $$Nederland lijkt een ideaal land voor het kweken van eendenkroos. In het groeiseizoen kan plaatselijk vanzelf een dichte kroosbedekking op sloten en plassen ontstaan, vooral in gebieden met intensieve landbouw.$$, 'inline'),
  ('bd1b320c-a15e-4ea5-a96d-94a0fb4f3559', '35e4bc54-ec50-4252-a16e-984ef858833e', $$groeisnelheid van drie eendenkroossoorten bij verschillende watertemperaturen (afbeelding 3)$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context5.png$$,
   $$Eendenkroos bereikt in Nederland rond augustus zijn hoogste bedekkingsgraad. De invloed van de temperatuur is in het laboratorium bepaald onder verder gelijke en optimale omstandigheden. In afbeelding 3 is de relatie tussen de groeisnelheid van drie eendenkroossoorten en de watertemperatuur weergegeven.
afbeelding 3: grafiek met op de x-as de watertemperatuur (°C, van 0 tot 40) en op de y-as een maat voor de groeisnelheid (van 0 tot 0,4), met drie lijnen voor Lemna minor, Lemna turionifera en Spirodela polyrhiza. Elke lijn stijgt vanaf 0°C naar een optimumtemperatuur en neemt daarna weer snel af.$$, 'inline'),
  ('65e090dc-9841-4485-b587-cd47a80e8717', '35e4bc54-ec50-4252-a16e-984ef858833e', $$vereiste hoge opbrengst van eendenkroos als veevoer$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context6.png$$,
   $$Eendenkroos dat wordt gekweekt voor veevoer moet een hoge opbrengst hebben.$$, 'inline'),
  ('0ade5253-6bb1-4ef3-a2be-d32d2139444a', '35e4bc54-ec50-4252-a16e-984ef858833e', $$invloed van licht op de groeisnelheid van eendenkroos$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context7.png$$,
   $$Naast de temperatuur beïnvloedt ook de factor licht overdag de groeisnelheid en dus de opbrengst van eendenkroos. Zo zal op een bewolkte dag de groei minder zijn dan op een zonnige dag.$$, 'inline'),
  ('174c5b69-9be7-4642-9ee3-7cd22d512028', '35e4bc54-ec50-4252-a16e-984ef858833e', $$nadelig effect van een dicht kroosdek op het zuurstofgehalte van het water$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context8.png$$,
   $$Een dicht kroosdek is nadelig voor het andere waterleven in een sloot, doordat het kan leiden tot een laag zuurstofgehalte van het water.$$, 'inline'),
  ('20d71c61-4f81-45c8-9df8-4771759bf7a6', '35e4bc54-ec50-4252-a16e-984ef858833e', $$verschuiving van de stikstofbalans van nitraat naar ammonium onder een dicht kroosdek$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context9.png$$,
   $$Eendenkroos neemt bij voorkeur ammonium op als stikstofbron. Bij het oogsten van eendenkroos voor veevoer, wordt getracht een zo dicht mogelijk kroosdek te handhaven en alleen de kroosaangroei te oogsten. Door het blijvend dichte kroosdek wordt algengroei geremd en verschuift de stikstofbalans in de sloot van nitraat naar ammonium.$$, 'inline'),
  ('08d81031-6000-48da-84d5-ce01e669abb4', '35e4bc54-ec50-4252-a16e-984ef858833e', $$beperkte voedingswaarde van kroos maar ecologisch duurzamer dan sojateelt$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-context10.png$$,
   $$Uit het onderzoek van Wageningen UR blijkt dat gedroogd eendenkroos niet de hoge voedingswaarde van soja heeft en daardoor slechts een deel van de eiwitlevering door soja kan vervangen. Toch biedt kroos perspectief omdat het gebruik ervan in veevoer ecologisch duurzamer is dan het gebruik van sojabrokken.$$, 'inline'),
  ('e440d010-c89e-40e5-beef-46162e76e1c1', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$tekort aan donorbloed en onderzoek naar kunstbloed met wadpieren-Hb$$,
   $$biologie-vwo-2016-ii-kunstbloed-context1.png$$,
   $$Bloedbanken kampen voortdurend met een tekort aan veilig bloed voor bloedtransfusies. Vandaar dat al lange tijd wordt gezocht naar bloedvervangers. Franse celbiologen onderzoeken de bruikbaarheid van kunstbloed met hemoglobine uit Zeeuwse wadpieren.$$, 'inline'),
  ('d5911543-665d-43f3-9a71-b265121c2cbb', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$kunstbloed zonder bloedcellen met vrije hemoglobinemoleculen$$,
   $$biologie-vwo-2016-ii-kunstbloed-context2.png$$,
   $$Door bij een bloedtransfusie kunstbloed zonder bloedcellen te gebruiken, voorkom je klontering van het bloed. Rode bloedcellen zijn echter belangrijk voor het vervoer van zuurstof. Om kunstbloed te verkrijgen met een grote capaciteit voor zuurstoftransport wordt geëxperimenteerd met vrije hemoglobinemoleculen (Hb) in een fysiologische zoutoplossing. Deze Hb kan van menselijke of dierlijke herkomst zijn.$$, 'inline'),
  ('6483cb56-6db4-49f1-9ab1-4e25f2de63ca', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$verwerking van donorbloed tot universeel donorbloed (bloedgroep 0)$$,
   $$biologie-vwo-2016-ii-kunstbloed-context3.png$$,
   $$Donorbloed wordt gesorteerd op bloedgroep opgeslagen. Na verwijdering van het bloedplasma kunnen de rode bloedcellen zes weken gekoeld worden bewaard in een fysiologische zoutoplossing. Indien bij een bloedtransfusie alleen rode bloedcellen (in een fysiologische zoutoplossing) worden gebruikt, kan bloedgroep 0 fungeren als universele bloeddonor.$$, 'inline'),
  ('a4977439-722e-45f8-b206-aad4eddf260b', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$geringe CO₂-transportcapaciteit van Hb-kunstbloed door het ontbreken van rode bloedcellen$$,
   $$biologie-vwo-2016-ii-kunstbloed-context4.png$$,
   $$Uit testen met verschillende soorten Hb-kunstbloed is gebleken dat vrije Hb-moleculen efficiënt zuurstof transporteren. Net als in normaal bloed (volbloed) is de Hb in kunstbloed ook in staat CO₂ te binden en af te geven.
Doordat rode bloedcellen ontbreken is de CO₂-transportcapaciteit van Hb-kunstbloed echter gering.$$, 'inline'),
  ('373dc203-5192-4878-b6a3-4e8c86134a99', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$bijwerkingen van Hb-kunstbloed: vaatvernauwing en ophoping van Hb-fragmenten in de nierbuisjes$$,
   $$biologie-vwo-2016-ii-kunstbloed-context5.png$$,
   $$Er zijn nog veel bijwerkingen bij gebruik van Hb-kunstbloed.
De vrije Hb-moleculen geven zeer snel O₂ af in de weefsels. Het menselijk lichaam reageert hierop door vaatvernauwing en dit veroorzaakt weer een verhoogde bloeddruk. Ook worden vrije Hb-moleculen in het lichaam snel afgebroken. Hb-fragmenten hopen zich vervolgens op in de nierbuisjes.$$, 'inline'),
  ('d48e72a2-2e33-4a6f-8bc4-510edfc84297', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$eigenschappen van hemoglobine uit de wadpier Arenicola marina$$,
   $$biologie-vwo-2016-ii-kunstbloed-context6.png$$,
   $$De wadpier Arenicola marina zou een oplossing kunnen bieden voor de problemen met kunstbloed, denken Franse celbiologen. De wadpier bezit Hb die ongeveer 50 maal zo groot is als menselijk Hb, stabieler is in de bloedstroom en een hogere O₂-affiniteit heeft. Kunstbloed met celvrije pieren-Hb bezit dan ook andere eigenschappen dan kunstbloed met celvrije mensen-Hb.$$, 'inline'),
  ('44b31dee-7657-4fd5-a978-85ea86851159', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$zuurstofverzadigingscurve M van kunstbloed met celvrije mensen-Hb (afbeelding 1)$$,
   $$biologie-vwo-2016-ii-kunstbloed-context7.png$$,
   $$Afbeelding 1 toont de zuurstofverzadiging van kunstbloed met celvrije mensen-Hb (curve M). De zuurstofverzadigingscurve van kunstbloed met celvrije pieren-Hb heeft een ander verloop.
afbeelding 1: grafiek met op de x-as de pO₂ (mmHg, van 0 tot 140) en op de y-as de O₂-verzadiging (%, van 0 tot 100), met een S-vormige curve M voor kunstbloed met celvrije mensen-Hb.$$, 'inline'),
  ('6f1226b7-97c6-485e-90d6-afbbd2094353', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$zuurstofverzadigingscurves L en R ten opzichte van curve M$$,
   $$biologie-vwo-2016-ii-kunstbloed-context8.png$$,
   $$In de afbeelding zijn twee andere zuurstofverzadigingscurves, L en R, geschetst; een naar links (L) en een naar rechts (R) verschoven ten opzichte van de curve M (van kunstbloed met celvrije mensen-Hb).$$, 'inline'),
  ('544473e9-4831-4fde-aacb-b350a6dfa824', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$verwachting dat kunstbloed met pieren-Hb geen nierschade veroorzaakt$$,
   $$biologie-vwo-2016-ii-kunstbloed-context9.png$$,
   $$De celbiologen verwachten dat kunstbloed met celvrije pieren-Hb geen schade aan de nieren zal veroorzaken.$$, 'inline'),
  ('e343fd6f-a854-470f-b8b4-097e5efb2552', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$experimentopzet met vier groepen muizen getest op afweerreactie tegen pieren-Hb (afbeelding 2)$$,
   $$biologie-vwo-2016-ii-kunstbloed-context10.png$$,
   $$Voordat het kunstbloed met celvrije pieren-Hb bij mensen kan worden toegepast, is het getest in muizen. Er werd onder andere onderzocht of pieren-Hb tot een afweerreactie bij de muizen leidt.
Daarvoor werden vier groepen van tien muizen gebruikt.
De muizen uit de controlegroep 1 werden geïnjecteerd met een 0,9% NaCl-oplossing, die uit groep 2 met een bufferoplossing zonder eiwitten, groep 3 werd geïnjecteerd met kippenalbumine in de bufferoplossing en groep 4 met de pieren-Hb in de buffer. Na drie weken werd de hoeveelheid IgE-antistoffen in het bloedserum van de muizen bepaald.
Resultaten van dit experiment zijn weergegeven in afbeelding 2.$$, 'inline'),
  ('df569d67-42f3-46d4-882e-ca8ad6b546ff', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$IgE-antistofconcentraties in het bloedserum van de muizengroepen (afbeelding 2)$$,
   $$biologie-vwo-2016-ii-kunstbloed-context11.png$$,
   $$afbeelding 2: staafdiagram met op de y-as de serumconcentratie IgE (ng/mL, van 0 tot 500) voor groep 2 (buffer), groep 3 (buffer met kippenalbumine) en groep 4 (buffer met pieren-Hb). Groep 4 heeft een significant hogere IgE-concentratie dan de andere groepen (aangegeven met een *).$$, 'inline'),
  ('ede78ffe-bebc-4916-9a97-99144691d1a5', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$twee hypothesen over de afweerreactie tegen pieren-Hb$$,
   $$biologie-vwo-2016-ii-kunstbloed-context12.png$$,
   $$Vooraf waren twee hypothesen opgesteld:
1 De muizen zijn in staat om een afweerreactie te ontwikkelen.
2 Er is geen significante afweerreactie tegen pieren-Hb.
Beide hypothesen worden door de resultaten van dit experiment ondersteund.$$, 'inline'),
  ('a3ab5ee9-4fae-4a92-a214-acd4e034a959', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$grote hoeveelheid wadpieren nodig; alternatief via recombinant-technologie$$,
   $$biologie-vwo-2016-ii-kunstbloed-context13.png$$,
   $$De celbiologen die de eerste testen met kunstbloed van pieren hebben uitgevoerd, zijn enthousiast omdat er geen bijwerkingen zijn gevonden in de muizen. Wadpieren kunnen hiervoor gekweekt worden, maar voor 600 mL kunstbloed met pieren-Hb is een kilo wadpieren nodig.
De pieren-Hb kan ook met behulp van recombinant-technologie worden gemaakt.$$, 'inline'),
  ('f4fff662-9c5f-4640-ae1b-81b4c2f3f487', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$productie van wadpieren-Hb door recombinante bacteriën via copyDNA en plasmide$$,
   $$biologie-vwo-2016-ii-kunstbloed-context14.png$$,
   $$Voor het produceren van dierlijke eiwitten worden vaak bacteriën gebruikt. Door middel van reversetranscriptase wordt copyDNA gemaakt, dat vervolgens wordt 'geplakt' in een plasmide. Na inbrengen van het plasmide in de bacteriën kunnen de recombinante bacteriën de wadpieren-Hb gaan produceren.$$, 'inline'),
  ('d39a0c88-ba3f-4dc4-8b12-76d4bc9bb703', '9713ea91-93fc-4e57-bbcf-c9c01138c917', $$beschikbare materialen voor de productie van recombinant pieren-Hb$$,
   $$biologie-vwo-2016-ii-kunstbloed-context15.png$$,
   $$Materialen die onderzoekers kunnen bestellen zijn:
1 menselijk weefsel;
2 wadpierweefsel;
3 gezuiverde Hb van de mens;
4 gezuiverde Hb van de wadpier.$$, 'inline'),
  ('287b7fe2-37d2-4ec3-b0bc-678e14d1b7e4', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$dreigend wereldwijd voedseltekort en ontwikkeling van Quorn uit de schimmel Fusarium venenatum$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context1.png$$,
   $$Vanwege het dreigende wereldwijde voedseltekort ging een Britse industrieel op zoek naar een eiwitbron die als alternatief voor vlees kan dienen. Zijn onderzoeksteam vond een schimmel die de basis vormt voor vleesvervangers die inmiddels op de markt zijn gebracht onder de merknaam Quorn®.$$, 'inline'),
  ('42c59608-26dd-43f8-a6fa-d5eba6367f11', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$kweken van Fusarium venenatum in een airlift-bioreactor (afbeelding 1 en 2)$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context2.png$$,
   $$De eiwitrijke, dradenvormende schimmel Fusarium venenatum wordt opgekweekt in 50 meter hoge 'airlift-bioreactoren' waarin voortdurend een koolstofbron (glucose uit mais), een stikstofbron (ammonium), sporenelementen en zuurstof aan het medium worden toegevoegd (afbeelding 1). In de vloeistof die wordt afgetapt bevindt zich de oogst: eiwitrijke schimmeldraden (afbeelding 2).
afbeelding 1: schema van de airlift-bioreactor met toevoer van glucose, mineralen, O₂ en NH₃ onderin, een neergaande en een opgaande buis, afvoer van CO₂ bovenin, een warmtewisselaar en een stoominlaat, met onderaan de oogst van mycoproteïnes; de RNA-reductie vindt later in het proces plaats.
afbeelding 2: foto van de schimmel Fusarium venenatum.
De afgetapte vloeistof wordt kort verhit en gecentrifugeerd. Op deze wijze wordt 300 kg eiwitrijke biomassa per uur verkregen. Deze mycoproteïne-pasta wordt vermengd met onder andere smaakstoffen en verder verwerkt tot verschillende vleesvervangers.$$, 'inline'),
  ('2fccb239-ec6f-4a77-9bac-d21381ce33ae', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$de schimmel wordt niet tot de producenten gerekend$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context3.png$$,
   $$De schimmel produceert eiwitrijke biomassa. Toch is de rol van deze schimmel in de kringloop van stoffen niet die van een producent.$$, 'inline'),
  ('3eda6fc3-0b5f-448b-9d35-e135e7d6331c', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$aerobe en anaerobe dissimilatie door Fusarium venenatum in de reactor$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context4.png$$,
   $$De schimmel F. venenatum kan zowel anaeroob als aeroob dissimileren. Doordat er continu zuurstof wordt toegevoegd aan de vloeistof in de reactor, blijft de dissimilatie aeroob en wordt anaerobe dissimilatie voorkomen.$$, 'inline'),
  ('e88167e3-c12c-491c-ad0f-8482ce7f730a', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$regeling van de flow (D=F/V) voor een optimale groeisnelheid in de reactor$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context5.png$$,
   $$In de reactor wordt voortdurend vloeistof toegevoegd en een even grote hoeveelheid vloeistof afgevoerd. Deze hoeveelheid wordt bepaald met de formule D = F/V, waarbij F de flow (doorloopsnelheid) is in liter per uur en V het reactorvolume in liters. D is dus het deel van de vloeistof in het vat dat in een uur vervangen wordt.
De flow is zo afgesteld dat de groeisnelheid, en dus de opbrengst van de schimmel, optimaal is.$$, 'inline'),
  ('35b2da6a-9e9a-405d-95b0-f30328aecc44', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$verlaging van het nucleïnezurengehalte in de mycoproteïne-pasta$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context6.png$$,
   $$Snel delende cellen van micro-organismen produceren veel RNA. Voor de voedselconsumptie is het een probleem dat cellen van F. venenatum een hoog gehalte aan nucleïnezuren bevatten. Vóór de verwerking tot het eindproduct wordt daarom het gehalte aan nucleïnezuren in de mycoproteïne-pasta verlaagd.$$, 'inline'),
  ('8908353b-6e54-458a-8826-03e3c2d1f633', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$vertering van RNA tot urinezuur en het ontstaan van jicht (afbeelding 3)$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context7.png$$,
   $$RNA in voedingsmiddelen wordt in het spijsverteringskanaal verteerd tot stikstofbasen, fosfaten en suikers. Afbraak van bepaalde stikstofbasen leidt tot de vorming van urinezuur (zie afbeelding 3).
afbeelding 3: structuurformule van urinezuur.
Wanneer voedingsmiddelen veel RNA bevatten, ontstaat een hoog gehalte aan urinezuur in het bloed dat niet volledig door de nieren kan worden uitgescheiden. Het hoopt dan op tot kristallen in de nieren (nierstenen).
Er ontstaan echter ook kristallen in bepaalde urinezuur gewrichten die daardoor pijnlijk stijf worden. Deze aandoening staat bekend als jicht.$$, 'inline'),
  ('7e8e1080-142e-4ed6-94f2-0523e4a48223', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$delen van het spijsverteringsstelsel$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context8.png$$,
   $$Delen van het spijsverteringsstelsel zijn:
1 maag;
2 dunne darm;
3 dikke darm.$$, 'inline'),
  ('1baa9df3-da8b-4b96-8d60-c7dc22f7913b', 'e0ccb1f1-289d-41d2-9518-1dd500420820', $$de meest voorkomende stikstofbasen$$,
   $$biologie-vwo-2016-ii-schimmel-als-eiwitbron-context9.png$$,
   $$De meest voorkomende stikstofbasen zijn adenine, cytosine, guanine, thymine en uracil.$$, 'inline'),
  ('e8d821b1-3282-4da2-95d2-b613765cb2f7', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$duikcapaciteit van zeezoogdieren als evolutionaire aanpassing$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context1.png$$,
   $$Evolutiebiologen en fysiologen vragen zich af hoe de fenomenale duikcapaciteit van zeezoogdieren zich heeft ontwikkeld nadat deze dieren het land weer verruilden voor het water. Om die vraag te beantwoorden, onderzoeken ze bij zeezoogdieren de aanpassingen op organismaal en moleculair niveau.$$, 'inline'),
  ('d18a6440-3a13-45d3-b3f7-217652b9efb5', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$grootteverschillen tussen zeezoogdieren en de duikreflex bij de zeeolifant (afbeelding 1)$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context2.png$$,
   $$Zeezoogdieren variëren enorm in grootte en gewicht: een zeeolifant-mannetje kan tot 4000 kg zwaar worden, de gewone zeehond 'maar' 150 kg. Zeeolifanten (zie afbeelding 1) zijn experts in duiken; ze kunnen langer dan twee uur onder water blijven zonder adem te halen. Als een zeeolifant onder water op jacht gaat, treedt de 'duikreflex' op: een sterke daling van de hartslagfrequentie en een vaatvernauwing, waardoor de bloedtoevoer naar perifere organen vermindert.
afbeelding 1: foto van een zeeolifant.$$, 'inline'),
  ('f641e169-7149-43c9-865d-1c02d4d53d95', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$lage oppervlakte-inhoud ratio bij zwaardere zeezoogdieren en twee beweringen daarover$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context3.png$$,
   $$De maximale duiktijd blijkt relatief langer te zijn bij de zwaardere soorten zeezoogdieren. Dat heeft onder andere te maken met hun lage oppervlakte-inhoud ratio.
Twee beweringen over een relatief lage oppervlakte-inhoud ratio zijn:
1 Er is minder energie nodig voor warmteopwekking.
2 De dode ruimte van de longen is groter.$$, 'inline'),
  ('f9abd4c4-e28a-47fd-a6ad-8fe16db92cd6', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$veranderingen in milt en bloedtoevoer naar het hart tijdens de duikreflex (afbeelding 2)$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context4.png$$,
   $$De prikkel voor het optreden van de duikreflex is het nat worden van het voorhoofd van het dier. Met dat gegeven konden de Canadese onderzoekers Thornton en Hochachka in het laboratorium duikfysiologisch onderzoek doen aan jonge zeeolifanten.
Een van de waarnemingen is dat het volume van de milt, direct bij het begin van een 'laboratoriumduik' door samentrekking meer dan halveert. Na de duik ontspant de milt en vult die zich weer met rode bloedcellen die verzadigd zijn met zuurstof.
Een ander opvallend resultaat is het ontstaan van een met bloed gevulde ruimte tussen het middenrif en de lever, doordat bij de duikreflex een kringspier om de holle ader samentrekt en zo de toevoer naar het hart reguleert. Beide veranderingen zijn in afbeelding 2 schematisch weergegeven.
afbeelding 2: twee tekeningen van de buikholte, 'voor de duik' en 'bij begin van duik', met hart, kringspier om de onderste holle ader, middenrif, lever, milt en poortader. Bij begin van de duik is de milt sterk verkleind en is er een met bloed gevulde ruimte ontstaan tussen middenrif en lever.$$, 'inline'),
  ('61e6e79d-2112-4f4e-be9c-e7eff1438bbf', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$hoog myoglobinegehalte bij zeezoogdieren en de bouw van het myoglobine-eiwit$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context5.png$$,
   $$Zeezoogdieren hebben behalve de duikreflex nog meer aanpassingen die de lange duiktijden mogelijk maken. Zo hebben ze een relatief hoog gehalte aan myoglobine, tot wel twaalf keer zo hoog als bij mensen. Myoglobine is een aan hemoglobine verwant eiwit dat aanwezig is in spieren en daar als zuurstofreservoir functioneert.
Myoglobine van zoogdieren bestaat uit één globine-eiwit met één heemgroep. Het globine-eiwit bestaat uit 153 aminozuren met acht alfa-helices.$$, 'inline'),
  ('26fbab69-4b7b-4c98-8a05-53cff6acdc11', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$correlatie tussen ZMb en [Mb]max bij land- en waterzoogdieren (afbeelding 3, diagram 1 en 2)$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context6.png$$,
   $$De relatieve hoeveelheid myoglobine in het spierweefsel van zoogdieren is een indicatie voor de duikcapaciteit. Daarom bepaalden de Britse onderzoekers Mirceta en Berenbrink in spierweefsel van verschillende land- en waterzoogdieren de maximale myoglobineconcentratie, de [Mb]max. Ook bepaalden ze de aminozuurvolgorde van die myoglobinemoleculen en daarmee berekenden ze de netto positieve lading van deze eiwitten, de ZMb. Er bleek een duidelijke correlatie (zie afbeelding 3): hoe hoger de berekende positieve lading (ZMb), hoe hoger de [Mb]max.
In diagram 1 is voor de [Mb]max een lineaire schaal gebruikt, in diagram 2 zijn dezelfde gegevens in een logaritmische schaal uitgezet.
afbeelding 3: twee spreidingsdiagrammen (diagram 1 met lineaire schaal, diagram 2 met logaritmische schaal) van [Mb]max tegen ZMb, met landdieren (open cirkels), waterdieren (gevulde cirkels) en semi-waterdieren (grijze cirkels). Beide diagrammen laten zien dat waterdieren zowel een hogere ZMb als een hogere [Mb]max hebben dan landdieren, met semi-waterdieren en enkele silhouetten (varken, zeehond) ter illustratie.$$, 'inline'),
  ('8ea05903-6cb9-42d6-84f4-025c558ef389', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$elektroforese-gel met myoglobines van verschillende zoogdieren (afbeelding 4)$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context7.png$$,
   $$Om de betrouwbaarheid van hun berekening van de ZMb te testen lieten de onderzoekers myoglobines van verschillende zoogdieren in een elektroforese-gel lopen. De resultaten daarvan staan in afbeelding 4.
afbeelding 4: elektroforesegel met banden van de myoglobine van verschillende zoogdiersoorten, met + bovenaan (positieve pool) en − onderaan (negatieve pool); de banden zijn over verschillende afstanden richting de positieve pool verplaatst.$$, 'inline'),
  ('47ec7373-7784-4981-8dcd-93043c3a7e3c', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$stamboom (cladogram) van roofdieren met ZMb-waarden en mutaties in myoglobine (afbeelding 5)$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context8.png$$,
   $$In afbeelding 5 zijn de ZMb-waardes in verband gebracht met de veranderingen in myoglobine in de loop van de evolutie van de roofdieren.
afbeelding 5: cladogram van de roofdieren, uitgaand van een gemeenschappelijke voorouder, met de takken zeehonden, vinpotigen (oorrobben en walrussen), marterachtigen, beren, hondachtigen en katachtigen. Bij elke tak zijn de opgetreden aminozuurmutaties in myoglobine aangegeven (bijvoorbeeld +Q113H: het 113e aminozuur is veranderd van glutamine (Q) in histidine (H), waardoor de lading positiever (+) is geworden; een − geeft een afname van de lading aan). Bij elke soort staat de bijbehorende ZMb-waarde vermeld, aflopend van 4,33 bij de zeehonden tot 0,96 bij de kat.
Op een aantal plaatsen zijn de mutaties in de aminozuurvolgorde van myoglobine gegeven waardoor de lading is veranderd: +Q113H betekent in dit schema dat het 113e aminozuur van myoglobine is veranderd van glutamine (Q) in histidine (H) waardoor de lading positiever (+) is geworden.$$, 'inline'),
  ('1c6004e0-bf47-4e6c-a97c-286e4c52a913', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$aanname dat de ZMb van de laatste gemeenschappelijke voorouder van de roofdieren 1,26 bedraagt$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context9.png$$,
   $$In afbeelding 5 zijn de verschillen in de primaire structuur van myoglobine weergegeven zoals die bekend zijn van nu levende roofdieren.
De onderzoekers veronderstellen dat de ZMb van de laatste gemeenschappelijke voorouder van de roofdieren 1,26 bedraagt.$$, 'inline'),
  ('1b329f11-9b3e-4764-b3ad-2ee6d4874a78', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$DNA-basenvolgorde bepaalt de aminozuurvolgorde, niet andersom$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context10.png$$,
   $$Een groot deel van de gegevens uit deze stamboom is verkregen door analyse van basenvolgordes in het DNA, en niet door het bepalen van aminozuurvolgordes in myoglobine.
Op basis van de geanalyseerde basenvolgorde in het DNA kun je wel met zekerheid de aminozuurvolgorde van de myoglobine bepalen, maar andersom niet.$$, 'inline'),
  ('81f3d822-6f6a-4254-b965-a5b875a28164', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$schatten van de maximale duiktijd op basis van lichaamsgewicht en [Mb]max (afbeelding 6)$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context11.png$$,
   $$Het bepalen van de duiktijd van zeezoogdieren in de natuur is een complex en duur onderzoek. Mirceta en Berenbrink hebben een formule afgeleid waarmee ze een goede schatting kunnen maken van de maximale duiktijd van dieren (tmax) op basis van het lichaamsgewicht en de [Mb]max. Op deze manier kunnen ze ook een uitspraak doen over de duiktijd van dieren waarvan weinig of geen metingen bekend zijn, en zelfs van uitgestorven dieren.
Het verband tussen die drie grootheden voor nu levende zoogdieren is grafisch weergegeven in afbeelding 6.
afbeelding 6: dubbellogaritmisch diagram met op de x-as het lichaamsgewicht (kg, van 0,01 tot 100000) en op de y-as tmax (min, van 0,2 tot 120) en [Mb]max (mg/g, van 0,3 tot 50), met punten voor levende zoogdiersoorten en aangegeven gebieden voor otters, oorrobben en zeehonden; tmax neemt toe met het lichaamsgewicht en met de [Mb]max.$$, 'inline'),
  ('44888f01-c659-4164-801a-3d1b6e018fc4', '5ed4ee64-7d43-429e-9e8a-0b8d8716d8e6', $$de uitgestorven Enaliarctos als voorouder van de vinpotigen (afbeelding 7) en zijn geschatte lichaamsgewicht en ZMb$$,
   $$biologie-vwo-2016-ii-duikende-zeezoogdieren-context12.png$$,
   $$afbeelding 7: tekening van het uitgestorven dier Enaliarctos.
De uitgestorven Enaliarctos (zie afbeelding 7) wordt beschouwd als een voorouder van de vinpotigen die de overgang van land naar water markeert.
Uit vergelijking tussen fossiele skeletten van Enaliarctos en de bouw van huidige zeezoogdieren is afgeleid dat het lichaamsgewicht van Enaliarctos ongeveer 80 kilo moet zijn geweest. Mirceta en Berenbrink hebben berekend dat de ZMb van Enaliarctos ongeveer 3 is.
Met bovenstaande gegevens, het verband tussen ZMb en [Mb]max (in afbeelding 3 diagram 2 op pagina 14) en de gegevens in het diagram van afbeelding 6 op pagina 17 is het mogelijk de maximale duiktijd (tmax) van dit uitgestorven dier te benaderen.$$, 'inline'),
  ('b9459d45-3cde-4ca5-82fd-6c1232577dc6', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$onvruchtbaarheid door te weinig zaadcellen, oorzaak mogelijk in de botten$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context1.png$$,
   $$Onvruchtbaar door te weinig zaadcellen in je sperma? Onderzoek uit de Verenigde Staten toont aan dat de oorzaak hiervoor soms niet in de testes ligt, maar in de botten.$$, 'inline'),
  ('04a4dd6e-8b10-4c6f-95f6-014f95180426', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$hormonale regulatie van de spermatogenese door LH en FSH (afbeelding 1)$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context2.png$$,
   $$Voor een goede productie van zaadcellen (spermatogenese) is een hoge concentratie van androgenen, zoals testosteron, van belang.
In afbeelding 1 is schematisch weergegeven hoe de hypofysehormonen LH (ook wel ICSH genoemd) en FSH de spermatogenese in de testes beïnvloeden. De androgenen die gebonden aan ABP naar het lumen van de zaadbuisjes vervoerd worden, stimuleren de spermatogonia om zich te gaan delen.
Als een man weinig androgenen produceert, kan dat ook botontkalking tot gevolg hebben.
afbeelding 1: schema van de hormonale regulatie van de spermatogenese. De hypothalamus geeft RH af aan de hypofysevoorkwab, die daardoor LH en FSH afgeeft. LH stimuleert de cel van Leydig tot productie van testosteron (T) en oestrogeen (E); FSH stimuleert de cel van Sertoli, die inhibine en activine afgeeft en ABP produceert. Testosteron wordt, gebonden aan ABP, naar het lumen van het zaadbuisje getransporteerd en stimuleert daar de spermatogenese. E en T worden ook, gebonden aan SHBG, aan het bloed afgegeven en remmen via negatieve terugkoppeling de hypothalamus en de hypofysevoorkwab. Inhibine remt eveneens de hypofysevoorkwab.$$, 'inline'),
  ('dd78bd42-4400-47c9-a064-29f5f974fbc0', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$spermatogonia moeten zich mitotisch delen om de vruchtbaarheid te behouden$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context3.png$$,
   $$Voor behoud van de vruchtbaarheid is het noodzakelijk dat spermatogonia zich mitotisch delen en niet meiotisch.$$, 'inline'),
  ('f7824a2c-b795-411f-9a9b-e07f8c2b606f', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$gebruik van testosteronpreparaten verstoort het regelmechanisme en veroorzaakt onvruchtbaarheid$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context4.png$$,
   $$Er zijn mannen die testosteronpreparaten gebruiken om hun botdichtheid op peil te houden. Dit kan het natuurlijke regelmechanisme verstoren, met onvruchtbaarheid als gevolg.$$, 'inline'),
  ('5595e311-1108-4779-b046-4f1c85719746', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$experimentopzet met botcellen en Leydig-cellen om invloed van bothormonen op testosteronproductie te testen (afbeelding 2)$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context5.png$$,
   $$Mogelijk hebben bothormonen op hun beurt een effect op de geslachtsorganen en vruchtbaarheid. Een team van onderzoekers onderzocht dit met behulp van muizencellen. De opzet van het experiment is schematisch weergegeven in afbeelding 2.
afbeelding 2: schema van het experiment in drie stappen. Stap 1: in vitro worden osteoblasten (botvormende cellen), myoblasten (spiervormende cellen) en adipocyten (vetcellen) van de muis gekweekt. Stap 2: na 24 uur wordt de vloeistof uit de kweekschaaltjes (1 = osteoblasten, 2 = myoblasten, 3 = adipocyten) toegevoegd aan schaaltjes met (muizen)cellen van Leydig. Stap 3: na een uur wordt gemeten hoeveel testosteron er in elk van de drie schaaltjes is geproduceerd.$$, 'inline'),
  ('0923eb29-a093-4ea1-b852-0de58ad1ee12', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$geproduceerde hoeveelheid testosteron door Leydig-cellen na blootstelling aan stoffen van botcellen (afbeelding 3)$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context6.png$$,
   $$De resultaten van die metingen, plus die van een controleschaaltje, zijn weergegeven in afbeelding 3.
afbeelding 3: staafdiagram met op de y-as de geproduceerde testosteron (ng/mL/10³ cellen, van 0 tot 1,50) voor het controlemedium en voor de schaaltjes 1 (osteoblasten), 2 (myoblasten) en 3 (adipocyten). Alleen schaaltje 1 (osteoblasten) geeft een significant hogere testosteronproductie dan het controlemedium (aangegeven met een *).$$, 'inline'),
  ('2469deac-a28f-4924-be1e-40e9caf82dd8', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$twee beweringen over de interactie tussen botcellen en Leydig-cellen$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context7.png$$,
   $$Over de interactie tussen cellen uit het bot en Leydig-cellen in de testes wordt het volgende beweerd:
1 Leydig-cellen geven testosteron af dat osteoblasten stimuleert.
2 Osteoblasten geven een stof af die de testosteron-afgifte van Leydig-cellen stimuleert.$$, 'inline'),
  ('c5128ad1-4d5b-4613-aeab-e8610752400f', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$hypothese dat osteocalcine invloed heeft op de testes via de receptor GPRC6A (afbeelding 4)$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context8.png$$,
   $$De hypothese van de onderzoekers is dat het hormoon osteocalcine, geproduceerd door bot, de vruchtbaarheid van mannelijke muizen beïnvloedt. In afbeelding 4 is door de onderzoekers de interactie tussen testes en botten in een vereenvoudigd schema weergegeven.
afbeelding 4: schema met bot dat osteocalcine afgeeft, dat via het bloed de Leydig-cel in de testis bereikt en daar aan de receptor GPRC6A bindt; de Leydig-cel geeft testosteron af dat via het bloed de osteoblast in het bot bereikt en daar aan de testosteronreceptor bindt.$$, 'inline'),
  ('639e4dd6-3642-44dc-90e6-3ca2109167a0', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$binding van osteocalcine aan de receptor GPRC6A en van testosteron aan de testosteronreceptor$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context9.png$$,
   $$Osteocalcine beïnvloedt de testes door aan de receptor GPRC6A (zie afbeelding 4) van Leydig-cellen te binden. Testosteron beïnvloedt de osteoblasten in botten door aan de testosteronreceptor te binden.$$, 'inline'),
  ('b3a6dabd-be6c-4cd0-9e97-31728f5f10b8', '2c12cd26-b71e-432b-b1d3-72db00301ae9', $$verwachting dat regulatie bij de mens overeenkomt met muizen; mogelijke behandeling met osteocalcine$$,
   $$biologie-vwo-2016-ii-bot-bepaalt-vruchtbaarheid-context10.png$$,
   $$De onderzoekers verwachten dat de regulatie bij de mens grotendeels overeenkomt met de regulatie bij muizen.
Door onvruchtbare mannen te behandelen met osteocalcine kan de vruchtbaarheid misschien weer hersteld worden.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('1e555f5e-5ff4-416b-830e-147578a3f2b0', '35e4bc54-ec50-4252-a16e-984ef858833e', 1,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["intercellulaire ruimten", "drijfvermogen", "transportweefsel", "waterplant"]'::jsonb,
   $$Verklaren waarom een klein drijvend waterplantje geen hout- en bastvaten nodig heeft.$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-vraag1.png$$, $$Licht toe aan de hand van bovenstaande gegevens dat een eendenkroosblad:
− geen houtvaten nodig heeft
− en ook geen bastvaten nodig heeft.$$, array['7a83ca2f-82a6-4925-a1f1-e7cdb271bab2','ec3a4d17-c241-4b01-a40f-3789b4cc94ed']::uuid[]),
  ('b8616dd1-f781-4423-b78f-72242f10b918', '35e4bc54-ec50-4252-a16e-984ef858833e', 2,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
   '["eutrofiëring", "nutriëntenaanvoer", "landbouw", "populatiegroei"]'::jsonb,
   $$Verklaren waardoor landbouwgebieden een overmatige kroosbedekking op sloten veroorzaken.$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-vraag2.png$$, $$Leg uit waardoor vooral op de sloten in gebieden met intensieve landbouw een overmatige kroosbedekking kan ontstaan.$$, array['54236e0c-2336-4bce-a15a-beac8135b08a','41630ec4-e852-4f9f-9819-4a05e27c4382']::uuid[]),
  ('0c87c4c6-2842-4c69-a4aa-367f880ec7b1', '35e4bc54-ec50-4252-a16e-984ef858833e', 3,
   '[{"domain": "Molecuul- en Celniveau", "subdomain": "Stofwisseling van de cel"}]'::jsonb,
   '["enzymwerking", "temperatuuroptimum", "denaturatie", "reactiesnelheid"]'::jsonb,
   $$Verklaren waarom de groeisnelheid met de temperatuur stijgt en na het optimum weer daalt.$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-vraag3.png$$, $$− Geef een verklaring voor de stijging van de groeisnelheid met de temperatuur van het water tot aan de optimumtemperatuur.
− Verklaar waardoor bij temperaturen hoger dan de optimumtemperatuur er een snelle afname is van de groeisnelheid.$$, array['bd1b320c-a15e-4ea5-a96d-94a0fb4f3559']::uuid[]),
  ('0371444d-dea1-4273-b6e5-b605ed8c5f01', '35e4bc54-ec50-4252-a16e-984ef858833e', 4,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
   '["optimumtemperatuur", "standplaatsfactoren", "soortselectie"]'::jsonb,
   $$Op basis van een grafiek bepalen welke eendenkroossoort het beste past bij het Nederlandse klimaat.$$,
   $$biologie-vwo-2016-ii-eendenkroos-voor-de-koe-vraag4.png$$, $$Welke van de drie onderzochte eendenkroossoorten (zie afbeelding 3) is het meest geschikt voor gebruik in Nederlandse sloten?
A Lemna minor
B Lemna turionifera
C Spirodela polyrhiza$$, array['bd1b320c-a15e-4ea5-a96d-94a0fb4f3559','65e090dc-9841-4485-b587-cd47a80e8717']::uuid[]),
  ('df18ba26-aaa9-4588-9375-63034324025a', '35e4bc54-ec50-4252-a16e-984ef858833e', 5,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
